// The loading yak: Trot or Haul, picked at random once per mount. Inline SVG generated by
// scripts/logo/loader.py — ink = currentColor, accent = var(--accent); reduced motion → still yak.
import { useState } from "react";
import { YAK_LOADERS } from "./yakLoaders";

export type YakVariant = keyof typeof YAK_LOADERS;
const VARIANTS = Object.keys(YAK_LOADERS) as YakVariant[];

export const pickYak = (): YakVariant => VARIANTS[Math.floor(Math.random() * VARIANTS.length)] as YakVariant;

// small: a 16px yak beside a label in a tight slot (the Agents panel); default size comes from spa.css
export function YakLoader({ variant, small = false }: { variant?: YakVariant; small?: boolean }) {
  const [pick] = useState(() => variant ?? pickYak());
  return (
    <span
      className={`yak-loader${small ? " sm" : ""}`}
      data-yak={pick}
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: YAK_LOADERS[pick] }}
    />
  );
}
